"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[15977],{9385:e=>{e.exports=JSON.parse('{"title":"StageOnce: Speculative Cross-Job Data Staging for LLM Agent Fleets","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'26)","type":"Poster","date":"November, 2026","month":11,"year":2026,"tags":["LLM Agents","Data Staging","Speculative Execution","HPC I/O"],"links":{},"abstract":"Scientific workflows increasingly run as fleets of LLM agents analysing immutable datasets. On a shared compute node, independent staging repeats source reads and creates storage contention, while each job discovers its inputs during reasoning. StageOnce coordinates these speculative path predictions through a node-local daemon, coalescing concurrent misses into one immutable copy while preserving dataset versions and private outputs. Tools read staged inputs directly from the filesystem, without per-read coordination. Recorded-session replays in genomics and astronomy on SSD and HDD backends reduce fleet makespan by 31-51% at 12 concurrent jobs against independent staging. Logical staging remains one copy across every tested fleet size. An ablation isolates speculation, which reduces makespan by 8-49% against reactive shared caching. StageOnce beats independent staging when fleet demand exceeds what reasoning windows can hide and reuse amortises coordination overhead, while smaller working sets can make direct reads or prologue bulk copies preferable.","slug":"yildirim-2026-stageonce-6b8e"}')}}]);